"""
Redaction module for removing sensitive information from nested dictionaries.
"""

from typing import Any, Dict, List, Union

# Set of keys that should be redacted. Defined as a set for O(1) lookup.
SENSITIVE_KEYS = {"password", "token", "api_key", "ssn", "secret"}


def redact(record: Any) -> Any:
    """
    Recursively redact sensitive keys in a dictionary or list.

    Returns a deep copy of the input where values of keys matching 
    SENSITIVE_KEYS (case-insensitive) are replaced by '***'.

    Args:
        record: The data structure to redact. Can be a dict, list, or scalar.

    Returns:
        A copy of the record with sensitive information redacted.
    """
    if isinstance(record, dict):
        return {
            k: redact("***" if _is_sensitive(k) else v) 
            for k, v in record.items()
        }
    elif isinstance(record, list):
        return [redact(item) for item in record]

    # Return scalar values as-is. 
    # Note: If record was passed as '***' from the dict comprehension, it returns '***'.
    return record


def _is_sensitive(key: Any) -> bool:
    """Helper to check if a key is sensitive regardless of case."""
    if not isinstance(key, str):
        return False
    return key.lower() in SENSITIVE_KEYS


