"""
Module for redacting sensitive information from nested dictionaries.
"""

from typing import Any, Dict, List, Union

# Set of keys identified as sensitive.
SENSITIVE_KEYS = {"password", "token", "api_key", "ssn", "secret"}


def redact(record: Any) -> Any:
    """
    Returns a copy of the input record (dict, list, or primitive) where values 
    associated with sensitive keys are replaced by '***'.

    The redaction is case-insensitive and handles nested structures.

    Args:
        record: The data structure to redact.

    Returns:
        A copy of the record with sensitive values redacted.
    """
    if isinstance(record, dict):
        return {
            k: redact(v) if k.lower() not in SENSITIVE_KEYS else "***"
            for k, v in record.items()
        }
    elif isinstance(record, list):
        return [redact(item) for item in record]
    else:
        # Return primitive types as-is
        return record


if __name__ == "__main__":
