    test_data = {
        "user": "jdoe",
        "Password": "supersecret123",
        "details": {
            "api_key": "abc-123-xyz",
            "SSN": "000-00-0000",
            "public_info": "Hello World",
            "nested_list": [
                {"token": "t1", "value": 1},
                {"token": "t2", "value": 2},
            ]
        },
        "tags": ["admin", "internal"]
    }

    expected = {
        "user": "jdoe",
